import static org.junit.jupiter.api.Assertions.*;import static cl.nexbyte.siger.institucional.nucleo.ContratosNucleo.*;
class ContinuidadAreasTest {
 @TempDir Path temp;DatosNucleoTest d;MateriasFixture m;AreasFixture f;NucleoU2 u;ContinuidadU2 c;final DatosAvisosTest.Tiempo reloj=new DatosAvisosTest.Tiempo();
 @BeforeEach void setup()throws Exception{d=new DatosNucleoTest(temp);m=new MateriasFixture(d,reloj);f=m.f;u=f.core.u2();c=f.core.continuidad();}
 @AfterEach void close(){if(d!=null)d.close();}
 NuevoDestino destino(){return new NuevoDestino("UPR","DEMO_SEDE_A",f.headB,"AREA_B");}
 UUID req(){var sol=u.distribuir(f.a(f.dist),UUID.randomUUID(),d.nuevaWeb(),new NucleoU2.Encaminar(0,new NuevoDestino("UPR","DEMO_SEDE_A",f.headA,"AREA_A"),"Evaluación por área",null)).id();return u.asumir(f.a(f.headA),UUID.randomUUID(),sol,new NucleoU2.Asumir(0,f.profA,"Asunción fundada","Sin domicilio utilizable: decisión fundada de jefatura")).id();}
 void denied(int s,Runnable r){assertEquals(s,assertThrows(FalloTecnico.class,r::run).status);}
 @Test void lecturaMateriaORolUnidadNoPermitenTransferirDerivarNiVerPaquete(){var q=req();var cas=u.abrirCaso(f.a(f.headA),UUID.randomUUID(),q,new NucleoU2.Apertura(0,f.profA,"Objetivo propio de área A")).id();m.clasificar(cas,0,"MAT_UPR",true);assertTrue(f.core.caso(f.a(m.upr),cas).soloLectura());denied(404,()->c.caso(f.a(m.upr),cas,true));denied(404,()->c.transferir(f.a(f.legacy),UUID.randomUUID(),q,new ContinuidadU2.Trasladar(1,destino(),"Sin área","No facultado")));denied(404,()->c.derivar(f.a(m.upr),UUID.randomUUID(),cas,new ContinuidadU2.Derivar(1,destino(),"Lectura no gestión","Paquete","Objetivo")));var p=c.derivar(f.a(f.headA),UUID.randomUUID(),cas,new ContinuidadU2.Derivar(1,destino(),"Derivación fundada","Resumen mínimo autorizado","Objetivo sucesor")).id();assertTrue(((List<?>)c.bandeja(f.a(m.upr)).get("derivaciones")).isEmpty());assertEquals(1,((List<?>)c.bandeja(f.a(f.headB)).get("derivaciones")).size());denied(404,()->f.core.caso(f.a(f.headB),cas));denied(404,()->c.decidirDerivacion(f.a(f.legacy),UUID.randomUUID(),p,new ContinuidadU2.Resolver(0,"ACEPTADA",f.profB,"Sin facultad de área")));}
 @Test void aliasDePersonaSolicitanteNoAceptaEnOtraArea()throws Exception{var q=req();String alias=f.user("alias.continuidad");var r=d.mapper.readValue(Base64.getDecoder().decode(d.db.sql.queryForObject("SELECT signed_payload FROM authority_batch ORDER BY revision DESC LIMIT 1",String.class)),AutoridadesInstitucionales.Registro12.class);var links=new ArrayList<>(r.vinculos());links.add(new AutoridadesInstitucionales.Vinculo(alias,"p-"+f.headA,f.start,f.end,ConcesionFixture.huella(d.db,alias)));f.importar(new AutoridadesInstitucionales.Registro12("1.2",r.revision()+1,f.clock.instant(),r.expira(),links,r.mandatos(),r.areas(),r.ambitos(),r.cambiosArea(),r.materias(),r.sedesRegionales(),r.ambitosMateria()));f.otorgar(alias,"COORDINADOR","AREA_B");var p=c.transferir(f.a(f.headA),UUID.randomUUID(),q,new ContinuidadU2.Trasladar(0,destino(),"Transferencia de principal","Resumen de coordinación")).id();denied(409,()->c.decidirTransferencia(f.a(alias),UUID.randomUUID(),p,new ContinuidadU2.Resolver(0,"ACEPTADA",null,"Misma persona por otra cuenta")));c.decidirTransferencia(f.a(f.headB),UUID.randomUUID(),p,new ContinuidadU2.Resolver(0,"ACEPTADA",null,"Aceptación de otra persona acreditada"));assertEquals("AREA_B",u.requerimiento(f.a(f.headB),q).get("area_id"));}
 @Test void areaObligatoriaYConcesionVencidaAfectanBandejaYDecision()throws Exception{var q=req();denied(409,()->c.transferir(f.a(f.headA),UUID.randomUUID(),q,new ContinuidadU2.Trasladar(0,new NuevoDestino("UPR","DEMO_SEDE_A",f.legacy),"No omitir área","Resumen")));var p=c.transferir(f.a(f.headA),UUID.randomUUID(),q,new ContinuidadU2.Trasladar(0,destino(),"Cambio fundado","Resumen")).id();reloj.avanzar(3601);assertTrue(((List<?>)c.bandeja(f.a(f.headB)).get("transferencias")).isEmpty());denied(404,()->c.decidirTransferencia(f.a(f.headB),UUID.randomUUID(),p,new ContinuidadU2.Resolver(0,"ACEPTADA",null,"Área vencida")));}
}
